    country: 'US',
    state: 'NE',
    alertLevel: 'high',
    sources: ["Douglas County Sheriff's Office (Nebraska)", 'WOWT'],
    sourceUrl: 'https://www.wowt.com/2026/07/28/omaha-woman-arrested-allegedly-stealing-770k-father-after-gaining-power-attorney/',
