    country: 'US',
    state: 'ND',
    alertLevel: 'high',
    sources: ["Suffolk County District Attorney's Office", 'KX News'],
    sourceUrl: 'https://www.suffolkcountyda.org/8500-returned-to-senior-citizen-after-scammers-tricked-her-into-mailing-u-s-currency/',
